    const plan = t.lp.l100;
    return `<div class="da-card"><span class="da-cap">${DT('Заправка', 'Tanken', 'Refuelling', 'Жанармай құю')} · ${esc(t.plate)}</span><div class="da-grid2"><label class="da-sub">${DT('Литры', 'Liter', 'Litres', 'Литр')}<input class="da-in" id="da_fl" type="number" value="320"></label><label class="da-sub">${DT('Цена, ₸/л', 'Preis, ₸/l', 'Price, ₸/l', 'Баға, ₸/л')}<input class="da-in" id="da_fp" type="number" value="295"></label><label class="da-sub">${DT('Одометр', 'Kilometerstand', 'Odometer', 'Одометр')}<input class="da-in" id="da_fo" type="number" value="${t.km + 420}"></label><label class="da-sub">${DT('Чек', 'Beleg', 'Receipt', 'Чек')}<button class="da-ghost" data-act="daReceipt" style="width:100%">${sh.receipt ? '✓ ' + sh.receipt : '📷 ' + DT('фото чека', 'Beleg fotografieren', 'photo of receipt', 'чек фотосы')}</button></label></div><button class="da-main" data-act="daFuel">${DT('Записать заправку', 'Tankvorgang buchen', 'Record refuelling', 'Жанармайды жазу')}</button><span class="da-sub">${DT('План расхода', 'Soll-Verbrauch', 'Planned consumption', 'Жоспарлы шығын')}: ${plan} l/100 km · ${DT('запись уходит в «Затраты» (FR-61)', 'Buchung geht an „Kosten“ (FR-61)', 'entry goes to Costs (FR-61)', 'жазба «Шығындарға» кетеді (FR-61)')}</span></div>
<span class="da-cap">${DT('Заправки рейса', 'Tankvorgänge', 'Fills on this trip', 'Рейс жанармайлары')}</span>${sh.fuel.map(f => `<div class="da-card"><div class="da-row"><b>${f.l} l · ${kzt(f.l * f.p)}</b><span class="da-sub">${f.t} · ${DT('одометр', 'km-Stand', 'odo', 'одометр')} ${f.o}</span></div><span class="${f.cons > plan * 1.1 ? 'da-bad' : 'da-ok'}">${String(f.cons).replace('.', ',')} l/100 km ${f.cons > plan * 1.1 ? DT('— выше плана', '— über Soll', '— above plan', '— жоспардан жоғары') : DT('— в норме', '— im Soll', '— on plan', '— қалыпты')}</span></div>`).join('') || `<span class="da-sub">—</span>`}`;
